const documents = $input.all()
  .map(i => i.json)
  .filter(j => j && j.job_id)
  .map(j => {
    const input = j.input && typeof j.input === 'object' ? j.input : {};
    const retryContext = input.retryContext && typeof input.retryContext === 'object' ? input.retryContext : {};
    const updateContext = input.updateContext && typeof input.updateContext === 'object' ? input.updateContext : {};
    const output = j.output && typeof j.output === 'object' ? j.output : null;
    const outputUpdateContext = output?.updateContext && typeof output.updateContext === 'object' ? output.updateContext : {};
    const outputRetryContext = output?.retryContext && typeof output.retryContext === 'object' ? output.retryContext : {};
    const generationMode = input.generationMode || retryContext.generationMode || output?.generationMode || output?.metadata?.generation_mode || null;
    const updateOfJobId = input.updateOfJobId || input.update_of_job_id || updateContext.previousJobId || updateContext.previous_job_id || retryContext.updateOfJobId || retryContext.update_of_job_id || output?.updateOfJobId || outputUpdateContext.previousJobId || output?.metadata?.update_of_job_id || null;
    const retryOfJobId = j.retry_of_job_id || input.retryOfJobId || input.retry_of_job_id || input.retryJobId || retryContext.retryOfJobId || retryContext.retry_of_job_id || output?.retryOfJobId || outputRetryContext.retryOfJobId || output?.metadata?.retry_of_job_id || null;
    return {
      id: j.job_id,
      jobId: j.job_id,
      projectId: j.project_id || output?.destination?.projectId || null,
      projectName: input.projectName || output?.projectName || 'Unknown project',
      documentType: input.documentType || output?.documentType || '',
      artifactLabel: input.documentType || output?.artifactLabel || '',
      createdAt: j.created_at,
      updatedAt: j.updated_at,
      status: j.status,
      url: output?.url || output?.confluenceUrl || '',
      input,
      output,
      error: j.error || null,
      requestedBy: j.requested_by || null,
      settingsVersion: j.settings_version || null,
      retryOfJobId,
      retriedByJobId: j.retried_by_job_id || null,
      retryStatus: j.retry_status || null,
      retryAttempt: Number(j.retry_attempt) || 0,
      generationMode,
      updateOfJobId
    };
  });
return [{ json: { documents } }];
